  async evidenceOverlay(params){if(params.getAll('generation').length!==1||[...params.keys()].some(k=>k!=='generation')||!hex(params.get('generation')))throw fail(400);if(params.get('generation')!==view.generation)return {status:'stale',generation:view.generation,entries:[]};return view.overlay;},
  async photo(params,wantsImage){const key=params.get('record'),hash=params.get('snapshot');if(params.getAll('record').length!==1||params.getAll('snapshot').length!==1||!key||key.length>300||!hex(hash))throw fail(400);if(hash!==view.reportHash)return service.photo(params,wantsImage);if(!photos.has(key))return {status:'unavailable',message:'This record is not part of the requested report.'};const digest=photos.get(key);if(!hex(digest))return {status:'unavailable',message:'No matching retained image is available for this evidence version.'};let value;try{value=await image(digest);}catch(e){if(e.code!=='ENOENT')throw e;return {status:'unavailable',message:'No matching retained image is available for this evidence version.'};}if(wantsImage)return value;const query=new URLSearchParams({record:key,snapshot:hash});return {status:'cached',sha256:digest,downloadedAt:null,thumbnail:'/api/reporting/photo/image?'+query,original:'/api/reporting/photo/image?'+query+'&original=1',reviewed:false};},
  gpsSnapshotFor:async hash=>hash===view.reportHash?{snapshotHash:hash,rows:[...gpsRows.values()]}:service.snapshotFor(hash)
